-- Importação inicial: Seguros_de_Aveiro_2026.xlsx (apólices de frota e motos de Aveiro).
--
-- Mapeamento do ficheiro para o modelo:
--   * RC → 'terceiros'; RC + DP na mesma matrícula → UM registo 'danos_proprios' com o valor da
--     viatura como valor seguro (a data em que a DP começou, se diferir, vai para as observações).
--   * Sem DATA FIM = sem termo (fim nulo). Com DATA FIM já passada = arquivado ('terminado').
--   * Área pelo centro de custo: VN→BMW VN, VO→BMW VU, 39VN737 (motos)→Motorrad, AVROF→Após-venda;
--     sem centro de custo (Caetano 4)→BMW VN. A confirmar e corrigir no tab Seguros.
--   * O ficheiro não traz quem pede nem prémio: solicitante = 'Por atribuir', prémio vazio.
--   * Empresa, centro de custo e local ficam nas observações.
-- Idempotente: não repete uma matrícula + início já registados.

-- Seguros de frota não têm data de fim: passa a ser opcional (sem termo até ser cancelado).
alter table public.seguros alter column fim drop not null;

insert into public.seguros
  (matricula, viatura, area, solicitante, data_pedido, inicio, fim, cobertura, capital_seguro, apolice, obs,
   arquivado, arquivado_em, motivo_arquivo)
